SELECT concat(toString(cohort), ' · ', toString(count()), if(count() = 1, ' user', ' users')) AS "Cohort (week of)",
       if(toDateTime(cohort + INTERVAL 0 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 0 WEEK)) / count(), 4), NULL) AS "W0",
       if(toDateTime(cohort + INTERVAL 1 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 1 WEEK)) / count(), 4), NULL) AS "W1",
       if(toDateTime(cohort + INTERVAL 2 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 2 WEEK)) / count(), 4), NULL) AS "W2",
       if(toDateTime(cohort + INTERVAL 3 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 3 WEEK)) / count(), 4), NULL) AS "W3",
       if(toDateTime(cohort + INTERVAL 4 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 4 WEEK)) / count(), 4), NULL) AS "W4",
       if(toDateTime(cohort + INTERVAL 5 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 5 WEEK)) / count(), 4), NULL) AS "W5",
       if(toDateTime(cohort + INTERVAL 6 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 6 WEEK)) / count(), 4), NULL) AS "W6",
       if(toDateTime(cohort + INTERVAL 7 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 7 WEEK)) / count(), 4), NULL) AS "W7",
       if(toDateTime(cohort + INTERVAL 8 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 8 WEEK)) / count(), 4), NULL) AS "W8",
       if(toDateTime(cohort + INTERVAL 9 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 9 WEEK)) / count(), 4), NULL) AS "W9",
       if(toDateTime(cohort + INTERVAL 10 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 10 WEEK)) / count(), 4), NULL) AS "W10",
       if(toDateTime(cohort + INTERVAL 11 WEEK) < {to:DateTime64(9)}, round(countIf(has(weeks, cohort + INTERVAL 11 WEEK)) / count(), 4), NULL) AS "W11"
FROM (
    SELECT c.cohort AS cohort, a.weeks AS weeks
    FROM (SELECT EnvId, UserId, toMonday(NewAt) AS cohort FROM (SELECT EnvId, UserId, if(reports = 1, signed_up_at, first_at) AS NewAt, reports AS ReportsSignups
FROM (
  SELECT EnvId, UserId, first_at, signed_up_at, has_signup, max(has_signup) OVER (PARTITION BY EnvId) AS reports,
         min(first_at) OVER (PARTITION BY EnvId) AS data_from
  FROM (
    SELECT EnvId, UserId, min(Timestamp) AS first_at, minIf(Timestamp, EventName = 'auth_signed_up') AS signed_up_at,
           toUInt8(countIf(EventName = 'auth_signed_up') > 0) AS has_signup
    FROM product_events
    WHERE UserId != '' AND EventName NOT IN ('auth_signed_out', 'auth_accounts') AND Props['forge.kind'] != 'state' AND Timestamp >= {to:DateTime64(9)} - INTERVAL 90 DAY AND Timestamp < {to:DateTime64(9)} AND (empty({env_ids:Array(String)}) OR has({env_ids:Array(String)}, EnvId))
    GROUP BY EnvId, UserId))
WHERE has_signup = 1 OR (reports = 0 AND first_at >= data_from + INTERVAL 7 DAY))
          WHERE NewAt >= toMonday({to:DateTime64(9)}) - INTERVAL 11 WEEK) AS c
    INNER JOIN (SELECT EnvId, UserId, groupUniqArray(toMonday(Timestamp)) AS weeks
                FROM product_events
                WHERE UserId != '' AND EventName NOT IN ('auth_signed_out', 'auth_accounts') AND Props['forge.kind'] != 'state' AND (empty({env_ids:Array(String)}) OR has({env_ids:Array(String)}, EnvId)) AND Timestamp >= toMonday({to:DateTime64(9)}) - INTERVAL 11 WEEK AND Timestamp < {to:DateTime64(9)}
                GROUP BY EnvId, UserId) AS a
      ON a.EnvId = c.EnvId AND a.UserId = c.UserId)
GROUP BY cohort ORDER BY cohort
